mapper.update:
UPDATE utb_app_ext_mst
SET app_kind = #{appTypeCode}
  , asset_no = #{ourRef}
  , case_code = #{caseNo}
  , dept_code = #{deptName}
  , app_name_ko = #{titleKo}
  , app_name_en = #{titleEn}
  , product_class = #{goodsClass}
  , individual_country_cnt = #{individualCountryCnt}
  , individual_country_content = #{designatedIndividual}
  , pct_cnt = #{pctCnt}
  , pct_content = #{designatedPct}
  , ep_cnt = #{epCnt}
  , ep_content = #{designatedEp}
  , madrid_cnt = #{madridCnt}
  , madrid_content = #{designatedMadrid}
  , international_design_cnt = #{internationalDesignCnt}
  , international_design_content = #{designatedIntlDesign}
  , grade = #{gradeCode}
  , independent_claim_cnt = #{independentClaims}
  , dependent_claim_cnt = #{dependentClaims}
  , spec_cnt = #{overseaSpecPage}
  , drawing_cnt = #{drawingCount}
  , global_app_no = #{globalAppNo}
  , representative_file_seq = #{representativeFileSeq}
  , give_up_content = #{abandonNote}
  , update_user = #{updateUser}
  , update_at = CURRENT_TIMESTAMP
  , note = #{note}
WHERE office_seq = #{officeSeq}
  AND app_ext_seq = #{appExtSeq}
  AND del_yn = 'N'

mapper.select:
SELECT page_data.*, ( SELECT string_agg(c.client_name_ko, '/') FROM utb_customer_mapp cm JOIN utb_customer c ON cm.office_seq = c.office_seq AND cm.customer_seq = c.customer_seq WHERE cm.office_seq = page_data."officeSeq" AND cm.tbl_seq = page_data."appExtSeq" AND cm.customer_category_code = 'client' AND cm.del_yn = 'N' AND c.del_yn = 'N' ) AS "clientNm", ( SELECT string_agg(c.client_name_ko, '/') FROM utb_customer_mapp cm JOIN utb_customer c ON cm.office_seq = c.office_seq AND cm.customer_seq = c.customer_seq WHERE cm.office_seq = page_data."officeSeq" AND cm.tbl_seq = page_data."appExtSeq" AND cm.customer_category_code = 'applicant' AND cm.del_yn = 'N' AND c.del_yn = 'N' ) AS "applicantNm" FROM ( /* 2. 검색 조건 필터링 및 페이징 처리를 먼저 수행 (최종 N건만 추출) */ SELECT * FROM ( SELECT mst.office_seq AS "officeSeq" , mst.app_ext_seq AS "appExtSeq" , mst.right_category AS "rightTypeCode" , fn_get_cd_nm('PAT_TYPE', mst.right_category) AS "rightTypeName" , mst.app_kind AS "appTypeCode" , fn_get_cd_nm('APP_TYPE_CD', mst.app_kind) AS "appTypeName" , mst.asset_no AS "ourRef" , mst.case_code AS "caseNo" , mst.dept_code AS "deptName" , mst.app_name_ko AS "titleKo" , mst.app_name_en AS "titleEn" , mst.product_class AS "goodsClass" , mst.individual_country_cnt AS "individualCountryCnt" , mst.individual_country_content AS "designatedIndividual" , mst.pct_cnt AS "pctCnt" , mst.pct_content AS "designatedPct" , mst.ep_cnt AS "epCnt" , mst.ep_content AS "designatedEp" , mst.madrid_cnt AS "madridCnt" , mst.madrid_content AS "designatedMadrid" , mst.international_design_cnt AS "internationalDesignCnt" , mst.international_design_content AS "designatedIntlDesign" , mst.grade AS "gradeCode" , fn_get_cd_nm('IP_GRADE_CD', mst.grade) AS "gradeName" , mst.independent_claim_cnt AS "independentClaims" , mst.dependent_claim_cnt AS "dependentClaims" , mst.spec_cnt AS "overseaSpecPage" , mst.drawing_cnt AS "drawingCount" , mst.global_app_no AS "globalAppNo" , mst.representative_file_seq AS "representativeFileSeq" , mst.give_up_content AS "abandonNote" , mst.create_user AS "createUser" , mst.create_at AS "createAt" , mst.update_user AS "updateUser" , mst.update_at AS "updateAt" , mst.del_yn AS "delYn" , mst.note AS "note" , vtdp."receiptDate" , vtdp."appDate" , vtdp."appCompleteDate" , vtdp."globalAppDate" , vtdp."regDate" , vtdp."regDecisionDate" , vtdp."regPaymentDate" , vtdp."abandonDate" , vpp."adminMgr" AS "adminMgr" , vpp."adminMgr_NM" AS "adminMgrNm" , vpp."caseMgr" AS "caseMgr" , vpp."caseMgr_NM" AS "caseMgrNm" , vpp.attorney AS "attorney" , vpp."attorney_NM" AS "attorneyNm" FROM utb_app_ext_mst mst LEFT JOIN v_total_duedate_pivot vtdp ON mst.app_ext_seq = vtdp.tbl_seq LEFT JOIN v_participant_pivot vpp ON mst.app_ext_seq = vpp.tbl_seq WHERE mst.office_seq = #{request.officeSeq} AND mst.del_yn = 'N' ) AS combined WHERE 1=1
/* 공통 코드 필터 */
AND NOT OR AND
("${cond.codeName}" = #{cond.codeValue})
/* 날짜 필터 */
AND NOT OR AND
(to_char("${filter.dateCode}"::timestamp, 'YYYYMMDD') BETWEEN #{filter.startDate} AND #{filter.endDate})
/* 텍스트 필터 및 고객명(EXISTS) 필터 */
AND NOT OR AND
EXISTS ( SELECT 1 FROM utb_customer_mapp cm JOIN utb_customer c ON cm.office_seq = c.office_seq AND cm.customer_seq = c.customer_seq WHERE cm.office_seq = #{request.officeSeq} AND cm.tbl_seq = combined."appExtSeq" AND cm.customer_category_code = 'client' AND cm.del_yn = 'N' AND c.del_yn = 'N' AND c.client_name_ko ILIKE CONCAT('%', #{tFilter.codeValue}, '%') )
AND NOT OR AND
EXISTS ( SELECT 1 FROM utb_customer_mapp cm JOIN utb_customer c ON cm.office_seq = c.office_seq AND cm.customer_seq = c.customer_seq WHERE cm.office_seq = #{request.officeSeq} AND cm.tbl_seq = combined."appExtSeq" AND cm.customer_category_code = 'applicant' AND cm.del_yn = 'N' AND c.del_yn = 'N' AND c.client_name_ko ILIKE CONCAT('%', #{tFilter.codeValue}, '%') )
AND NOT OR AND
("${tFilter.codeName}" ILIKE CONCAT('%', #{tFilter.codeValue, jdbcType=VARCHAR}, '%'))
ORDER BY "appExtSeq" DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}
) AS page_data

